<?php
require_once __DIR__ . '/../includes/auth.php'; requireAdmin(); $pageTitle='Overview'; $db=getDB(); $stats=[]; foreach(['users','deposits','withdrawals','packages'] as $table){$stats[$table]=(int)$db->query('SELECT COUNT(*) FROM '.$table)->fetchColumn();} $stats['pending_deposits']=(int)$db->query('SELECT COUNT(*) FROM deposits WHERE status="pending"')->fetchColumn(); $stats['pending_withdrawals']=(int)$db->query('SELECT COUNT(*) FROM withdrawals WHERE status="pending"')->fetchColumn(); $recent=$db->query('SELECT t.*,u.username FROM transactions t JOIN users u ON u.id=t.user_id ORDER BY t.created_at DESC,t.id DESC LIMIT 10')->fetchAll();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= e($pageTitle) ?> - <?= e(APP_NAME) ?></title><link rel="stylesheet" href="../assets/css/style.css"><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css"></head><body><?php include __DIR__.'/_header.php'; ?><div class="page-title"><span class="eyebrow">CONTROL CENTER</span><h1>Admin overview</h1><p class="muted">Review the activity of this demo installation.</p></div><div class="stat-grid"><div class="stat-card"><span>Total users</span><strong><?= e($stats['users']) ?></strong></div><div class="stat-card"><span>Pending deposits</span><strong><?= e($stats['pending_deposits']) ?></strong></div><div class="stat-card"><span>Pending withdrawals</span><strong><?= e($stats['pending_withdrawals']) ?></strong></div><div class="stat-card"><span>Packages</span><strong><?= e($stats['packages']) ?></strong></div></div><section class="panel"><div class="section-heading"><h2>Latest transactions</h2></div><div class="table-wrap"><table><thead><tr><th>User</th><th>Type</th><th>Amount</th><th>Status</th><th>Date</th></tr></thead><tbody><?php foreach($recent as $row): ?><tr><td><?= e($row['username']) ?></td><td><?= e(ucfirst($row['type'])) ?></td><td><?= formatCurrency($row['amount']) ?></td><td><span class="badge <?= e($row['status']) ?>"><?= e(ucfirst($row['status'])) ?></span></td><td><?= e(formatDate($row['created_at'])) ?></td></tr><?php endforeach; ?></tbody></table></div></section><?php include __DIR__.'/_footer.php'; ?></body></html>
